import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    k = int(next(it))

    times = []
    for i in range(n):
        times.append((int(next(it)), i + 1))  # Store original index

    # Sort by time required (ascending)
    times.sort()

    m = 0
    total = 0
    indices = []

    for time, idx in times:
        if total + time <= k:
            total += time
            indices.append(idx)
            m += 1
        else:
            break

    print(m)
    if m > 0:
        print(' '.join(map(str, indices)))

if __name__ == "__main__":
    solve()
"}

