def solve():
    n = int(input())
    t = list(map(int, input().split()))

    last_time = {}
    rooms = []

    for i, ti in enumerate(t, start=1):
        # i is current minute (1-indexed)
        # ti is the last time we were in this room (if we've been here before)

        # Check if we can reuse an existing room with last time ti

        # Use a dictionary to count how many rooms have a certain last time
        freq = {}
        for r in last_time:
            freq[last_time[r]] = freq.get(last_time[r], 0) + 1

        # If there's a room with last_time == ti, we can reuse it
        if freq.get(ti, 0) > 0:
            # Pick any such room (we don't care which one)
            for r in last_time:
                if last_time[r] == ti:
                    last_time[r] = i
                    break
        else:
            # Create a new room
            new_room = len(rooms) + 1
            rooms.append(new_room)
            last_time[new_room] = i

    print(len(rooms))

solve()
