def solve():
    n, m, k = map(int, input().split())
    powers = list(map(int, input().split()))
    schools = list(map(int, input().split()))
    chosen = set(map(int, input().split()))

    # For each school, find the strongest student
    school_strongest = {}
    for i in range(n):
        if schools[i] not in school_strongest:
            school_strongest[schools[i]] = (powers[i], i+1)  # (power, student_id)
        else:
            if powers[i] > school_strongest[schools[i]][0]:
                school_strongest[schools[i]] = (powers[i], i+1)

    # Count how many chosen students are NOT the strongest in their schools
    new_schools_needed = 0
    for student_id in chosen:
        idx = student_id - 1
        school = schools[idx]
        power = powers[idx]
        strongest_power, strongest_id = school_strongest[school]

        if strongest_id != student_id:
            new_schools_needed += 1

    print(new_schools_needed)

solve()
"}

