import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n, x, y = map(int, data[:3])

    # Check if solution is impossible
    if y * y + n - 1 < x:
        print(-1)
        return

    # Construct solution
    print(y - (n - 1))
    for _ in range(n - 1):
        print(1)

if __name__ == "__main__":
    solve()
"}

