import sys
import math

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    x = int(data[1])
    y = int(data[2])

    # Let's always put the large number first
    if n == 1:
        k = max(1, int(math.ceil(math.sqrt(x))))
        if k <= y and k*k >= x:
            print(k)
        else:
            print(-1)
        return

    # Set n-1 numbers to 1
    # Then find k such that (n-1) + k <= y and (n-1) + k^2 >= x
    remaining_sum = y - (n - 1)

    # Minimum k needed
    min_k = max(1, int(math.ceil(math.sqrt(x - (n - 1)))))

    if min_k > remaining_sum:
        print(-1)
    else:
        # Put the large number first
        print(remaining_sum)
        for _ in range(n - 1):
            print(1)

if __name__ == "__main__":
    solve()
"}

