# We need to partition into at least 2 segments with equal sum.
total_sum = sum(int(d) for d in digits)

if total_sum == 0:
    print("YES")
else:
    # Check all possible target sums that are divisors of total_sum with at least 2 segments
    possible_targets = set()
    for k in range(2, n + 1):
        if total_sum % k == 0:
            target = total_sum // k
            possible_targets.add(target)

    found = False
    # Try each possible target sum
    for target in possible_targets:
        current_sum = 0
        segment_count = 0
        for d in digits:
            current_sum += int(d)
            if current_sum == target:
                segment_count += 1
                current_sum = 0
                if segment_count >= 2:
                    found = True
                    break
        if found:
            break

    # Additional check for the case where the last segment might be exactly target
    # but we broke early before checking it (if we found two segments but the third might also be target)
    # Actually, if we have at least two segments, and total_sum == k * target, then the last segment will also sum to target.
    # So we only need count >= 2 at the end.
    if not found:
        current_sum = 0
        segment_count = 0
        for d in digits:
            current_sum += int(d)
            if current_sum == target:
                segment_count += 1
                current_sum = 0
        if segment_count >= 2:
            found = True

    print("YES" if found else "NO")
