import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    i = int(data[2])
    j = int(data[3])

    E = [[0.0] * (M + 2) for _ in range(N + 2)]

    for c in range(1, M + 1):
        E[N][c] = 0.0

    for r in range(N - 1, 0, -1):
        for c in range(1, M + 1):
            if r < N:
                moves = 1
                if c > 1:
                    moves += 1
                if c < M:
                    moves += 1
            else:
                moves = 0

            if moves == 0:
                continue

            val = 0.0
            if r < N:
                val += E[r+1][c]  # Down move
            if c > 1:
                val += E[r][c-1]  # Left move
            if c < M:
                val += E[r][c+1]  # Right move

            E[r][c] = 1.0 + val / moves

    print("{0:.10f}".format(E[i][j]))

if __name__ == "__main__":
    solve()
