from collections import deque

def solve():
    n, m = map(int, input().split())
    grid = []
    for _ in range(n):
        grid.append(list(input().strip()))

    # Find connected components of '.':
    visited = [[False for _ in range(m)] for _ in range(n)]
    components = []

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                # BFS to find component:
                q = deque()
                q.append((i, j))
                visited[i][j] = True
                component = []
                while q:
                    x, y = q.popleft()
                    component.append((x, y))
                    for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nx, ny = x+dx, y+dy
                        if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == '.' and not visited[nx][ny]:
                            visited[nx][ny] = True
                            q.append((nx, ny))
                components.append(component)

    # Check if any component has size 1 (isolated cell):
    for comp in components:
        if len(comp) == 1:
            print(-1)
            return

    # Assign colors (digits) to components such that adjacent components have different digits:
    # Build adjacency list for components:
    adj = [[] for _ in range(len(components))]

    for i, comp in enumerate(components):
        for x, y in comp:
            for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                nx, ny = x+dx, y+dy
                if 0 <= nx < n and 0 <= ny < m:
                    for j, comp2 in enumerate(components):
                        if (nx, ny) in comp2 and i != j:
                            adj[i].append(j)
                            break

    # Graph coloring - 2-coloring:
    color = [-1] * len(components)

    for start in range(len(components)):
        if color[start] == -1:
            color[start] = 0
            q = deque([start])
            while q:
                curr = q.popleft()
                for neighbor in adj[curr]:
                    if color[neighbor] == -1:
                        color[neighbor] = color[curr] + 1
                        q.append(neighbor)

    # Assign digits to the grid:
    result = [['.' for _ in range(m)] for _ in range(n)]

    for i, comp in enumerate(components):
        digit = color[i]
        for x, y in comp:
            result[x][y] = str(digit)

    for row in result:
        print(''.join(row))

solve()
