import sys
from collections import defaultdict

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    x = int(next(it))

    keyboard = []
    pos = defaultdict(set)
    for i in range(n):
        for j in range(m):
            c = next(it)
            keyboard.append(c)
            pos[c].add((i, j))

    posS = pos.get('S', set())

    # Precompute min_dist_to_S for each key position
    INF = float('inf')
    min_dist_to_S = [[INF] * m for _ in range(n)]

    for (s_i, s_j) in posS:
        for i in range(n):
            for j in range(m):
                dist = (i - s_i) ** 2 + (j - s_j) ** 2
                if dist < min_dist_to_S[i][j]:
                    min_dist_to_S[i][j] = dist

    # Precompute min distance from each letter to any Shift
    letter_min_dist_to_S = {}
    for c_lower in pos:  # only for lowercase letters? Actually all letters, but uppercase letters don't need it
        if c_lower == 'S':
            continue
        min_dist = INF
        for (i, j) in pos[c_lower]:
            if min_dist_to_S[i][j] < min_dist:
                min_dist = min_dist_to_S[i][j]
        letter_min_dist_to_S[c_lower] = min_dist

    q = int(next(it))
    T = ''.join(next(it))

    right_hand_count = 0
    for c in T:
        if c.islower():
            if len(pos[c]) == 0:
                print(-1)
                return
            # left hand only
        else:  # uppercase
            c_lower = c.lower()
            if len(pos[c_lower]) == 0:
                print(-1)
                return
            if len(posS) == 0:
                print(-1)
                return
            if letter_min_dist_to_S.get(c_lower, INF) > x * x:
                right_hand_count += 1

    print(right_hand_count)

if __name__ == '__main__':
    main()
