import sys

def solve():
    n, m = map(int, sys.stdin.readline().split())
    jiro_cards = []
    for _ in range(n):
        pos, s = sys.stdin.readline().split()
        jiro_cards.append((pos, int(s)))

    ciel_cards = []
    for _ in range(m):
        ciel_cards.append(int(sys.stdin.readline()))

    # DP: mask_jiro (n bits) and mask_ciel (m bits)
    dp = {}

    # Base case: no cards used
    dp[0, 0] = 0

    for mask_jiro in range(1 << n):
        for mask_ciel in range(1 << m):
            if (mask_jiro, mask_ciel) not in dp:
                continue

            current_damage = dp[mask_jiro, mask_ciel]

            # Check if Jiro has no cards left
            if mask_jiro == (1 << n) - 1:
                # Add remaining Ciel cards
                remaining = 0
                for i in range(m):
                    if not (mask_ciel & (1 << i)):
                        remaining += ciel_cards[i]
                dp[mask_jiro, mask_ciel] = current_damage + remaining
                continue

            # Try using any unused Ciel card on any unused Jiro card
            for c in range(m):
                if mask_ciel & (1 << c):
                    continue

                for j in range(n):
                    if mask_jiro & (1 << j):
                        continue

                    pos, strength_j = jiro_cards[j]
                    strength_c = ciel_cards[c]

                    if pos == 'ATK':
                        if strength_c >= strength_j:
                            # Attack ATK card
                            damage = strength_c - strength_j
                            new_mask_jiro = mask_jiro | (1 << j)
                            new_mask_ciel = mask_ciel | (1 << c)
                            if (new_mask_jiro, new_mask_ciel) in dp:
                                dp[new_mask_jiro, new_mask_ciel] = max(dp[new_mask_jiro, new_mask_ciel], current_damage + damage)
                            else:
                                dp[new_mask_jiro, new_mask_ciel] = current_damage + damage
                    else:  # DEF
                        if strength_c > strength_j:
                            # Attack DEF card
                            damage = 0
                            new_mask_jiro = mask_jiro | (1 << j)
                            new_mask_ciel = mask_ciel | (1 << c)
                            if (new_mask_jiro, new_mask_ciel) in dp:
