import sys

def solve() -> None:
    n = int(sys.stdin.readline())
    possible = set('abcdefghijklmnopqrstuvwxyz')
    determined = None
    excessive_shocks = 0

    for _ in range(n):
        line = sys.stdin.readline().strip().split()
        action_type = line[0]
        content = line[1]

        if action_type == '!':
            # Shock: selected letter is in content
            if determined is None:
                # We don't know yet
                possible &= set(content)
            else:
                # If already determined, this is an excessive shock
                excessive_shocks += 1
        elif action_type == '.':
            # No shock: selected letter is not in content
            if determined is None:
                # We don't know yet
                possible -= set(content)
            else:
                # If already determined, this is an excessive shock
                excessive_shocks += 1
        elif action_type == '?':
            # Guess: content is the selected letter
            if determined is None:
                determined = content
                # After guessing, no more excessive shocks

        if determined is not None:
            # After guessing, we know the answer
            if len(possible) > 1:
                # The answer should be in possible, but it's not unique
                pass
            elif len(possible) == 1:
                # The answer is determined
                pass
        else:
            if len(possible) == 1:
                # The selected letter is determined now
                determined = possible.pop()
                possible = set()
                # Any subsequent shocks are excessive

    print(excessive_shocks)

if __name__ == '__main__':
    solve()
