def solve():
    n, l, k = map(int, input().split())
    p = list(map(int, input().split()))
    a = list(map(int, input().split()))

    # dp[i][j][s]: probability after i tours, have won j tours, have space s
    # Also track the number of huge prizes we've won
    # dp[i][j][s][num_huge]: probability after i tours, have won j tours, have space s, have num_huge huge prizes

    dp = [[[[0.0 for _ in range(201)] for _ in range(201)] for _ in range(n+1)] for _ in range(201)]
    dp[0][0][k][0] = 1.0

    for i in range(n):
        for j in range(i+1):
            for s in range(201):
                for num_huge in range(201):
                    if dp[i][j][s][num_huge] == 0.0:
                        continue

                    # Lose tour i+1
                    dp[i+1][j][s][num_huge] += dp[i][j][s][num_huge] * (1.0 - p[i])

                    # Win tour i+1
                    if a[i] == -1:
                        # Huge prize - we need to carry 1 more huge prize
                        new_num_huge = num_huge + 1
                        if new_num_huge <= 200:
                            dp[i+1][j+1][s][new_num_huge] += dp[i][j][s][num_huge] * p[i]
                    else:
                        # Bag - we gain space
                        new_s = min(s + a[i], 200)
                        dp[i+1][j+1][new_s][num_huge] += dp[i][j][s][num_huge] * p[i]

    result = 0.0
    for j in range(l, n+1):
        for s in range(201):
            for num_huge in range(201):
                if num_huge <= s:
                    result += dp[n][j][s][num_huge]

    print(f"{result:.12f}")

