import sys

def solve(s):
    tokens = []
    i = 0
    n = len(s)

    # Parse the string into tokens
    while i < n:
        if s[i] == '':
            i += 1
        elif s[i].isdigit():
            # Parse a number
            start = i
            while i < n and s[i].isdigit():
                i += 1
            tokens.append(('num', s[start:i]))
        elif s[i] == ',':
            tokens.append(('comma', ','))
            i += 1
        elif s[i] == '.':
            if i + 2 < n and s[i+1] == '.' and s[i+2] == '.':
                tokens.append(('dots', '...'))
                i += 3
        else:  # space
            i += 1

    # Build result with proper spacing
    result = []
    prev_type = None

    for token_type, token_value in tokens:
        if result:
            # If there's a previous token, add space if needed
            if prev_type == 'comma':
                # Comma should be followed by exactly one space
                result.append(' ')
            elif prev_type == 'dots':
                # Dots should be followed by exactly one space
                result.append(' ')
            elif prev_type == 'num' and token_type == 'num':
                # Two numbers separated by spaces should have exactly one space
                result.append(' ')

        # Add the token
        result.append(token_value)

        prev_type = token_type

    return ''.join(result)

if __name__ == '__main__':
    s = sys.stdin.readline().strip()
    print(solve(s))
