    curr_valid = set()
    for k in valid_k:
        a_rot = (a + k) % n
        b_rot = (b + k) % n
        if a_rot > b_rot:
            a_rot, b_rot = b_rot, a_rot
        if (a_rot, b_rot) in segments:
            curr_valid.add(k)
    valid_k = curr_valid

if valid_k:
    print("Yes")
else:
