def is_bipartite(grid, n, m):
    color = [[-1] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and color[i][j] == -1:
                # Start BFS
                queue = [(i, j)]
                color[i][j] = 0
                while queue:
                    x, y = queue.pop(0)
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m:
                            if grid[nx][ny] == '.' and color[nx][ny] == -1:
                                color[nx][ny] = color[x][y] ^ 1
                                queue.append((nx, ny))
                            elif grid[nx][ny] == '.' and color[nx][ny] == color[x][y]:
                                return False, []
    return True, color

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, m = int(data[0]), int(data[1])
    grid = []
    index = 2
    for i in range(n):
        line = data[index:index+m]
        grid.append(line)
        index += m

    # Check if any cell needs to be filled
    has_empty = any(cell == '.' for row in grid for cell in row)
    if not has_empty:
        for row in grid:
            print(''.join(row))
        return

    is_bipartite, color = is_bipartite(grid, n, m)
    if not is_bipartite:
        print(-1)
        return

    # Output the solution
    for i in range(n):
        line = []
        for j in range(m):
            if grid[i][j] == '#':
                line.append('#')
            else:
                # Assign color 0 or 1
                line.append(str(color[i][j]))
        print(''.join(line))

if __name__ == '__main__':
    solve()
