def find_permutation(n, m, leaders):

    # If we have more steps than numbers, we might need to repeat values
    if m > n:
        # We might still have a valid solution if constraints are consistent
        pass

    # We need to assign values to each position i from 1 to n
    a = [0] * (n + 1)  # a[1..n]
    used = set()

    # Step 1: Find constraints for positions 2 to n
    for i in range(1, m):
        li = leaders[i - 1]
        li_plus_1 = leaders[i]

        if li_plus_1 == n:
            ai = n - li
        else:
            ai = li_plus_1 - li

        if ai < 1 or ai > n:
            return -1

        # If we have more steps than numbers, we might need to reuse values
        if m <= n and ai in used:
            return -1

        a[i + 1] = ai
        used.add(ai)

    # Step 2: Assign remaining values to unused positions
    if m <= n:
        for i in range(1, n + 1):
            if a[i] == 0:
                for val in range(1, n + 1):
                    if val not in used:
                        a[i] = val
                        used.add(val)
                        break

    # Step 3: Verify solution
    current_leader = leaders[0]
    for i in range(1, m):
        ai = a[i]
        new_leader = (current_leader + ai) % n
        if new_leader == 0:
            new_leader = n
        if new_leader != leaders[i]:
            return -1
        current_leader = new_leader

    return a[1:]

n, m = map(int, input().split())
leaders = list(map(int, input().split()))

perm = find_permutation(n, m, leaders)

if perm == -1:
    print(-1)
else:
    print(' '.join(map(str, perm)))
