def solve_knights(n):
    # We'll place knights in a regular pattern
    # Starting from (0, 0)
    knights = []
    knight_count = 0
    while knight_count < n:
        knights.append((knight_count, 0))
        knight_count += 1

    # Track which cells are attacked by how many knights
    attacked_cells = {}

    # Calculate which cells each knight attacks
    for x, y in knights:
        # Cells attacked by this knight
        attacked = [
            (x+2, y+1), (x+2, y-1), (x-2, y+1), (x-2, y-1),
            (x+1, y+2), (x+1, y-2), (x-1, y+2), (x-1, y-2)
        ]

        # Update attacked_cells
        for cell in attacked:
            attacked_cells[cell] = attacked_cells.get(cell, 0) + 1

    # Find cells that need new knights
    new_knights = []
    for cell, count in attacked_cells.items():
        if count >= 4:
            new_knights.append(cell)

    # Place new knights
    for x, y in new_knights:
        knights.append((x, y))

    return knights

