def is_lucky_ticket(digits):
    n = len(digits)
    total = sum(int(d) for d in digits)

    # Check if we can divide into segments with equal sum
    for k in range(1, total // 2 + 1):
        if total % k == 0:
            # Try to divide into segments with sum k
            current_sum = 0
            segment_count = 0

            for d in digits:
                current_sum += int(d)

                if current_sum == k:
                    current_sum = 0
                    segment_count += 1

            if segment_count >= 2:
                return True

    return False

