import sys

def harmonic_number(n):
    """Compute the nth harmonic number: H_n = 1 + 1/2 + 1/3 + ... + 1/n"""
    result = 0.0
    for i in range(1, n + 1):
        result += 1.0 / i
    return result

def main():
    input_line = sys.stdin.readline().strip()
    if not input_line:
        return
    n = int(input_line)
    result = harmonic_number(n)
    print(f"{result:.12f}")

if __name__ == "__main__":
    main()
"}

