def harmonic_number(n):
    """Compute the nth harmonic number: H_n = 1 + 1/2 + 1/3 + ... + 1/n using arbitrary precision"""
    # Use Python's built-in arbitrary precision with decimal
    from decimal import Decimal, getcontext
    getcontext().prec = 20  # Set precision higher than needed

    result = Decimal(0)
    for i in range(1, n + 1):
        result += Decimal(1) / Decimal(i)

    # Format to 15 decimal places as shown in examples
    return format(result, ".15f")

def main():
