import sys

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    if n == 0:
        print(0)
        return
    T = sum(a[i] * i for i in range(n))
    min_total = float('inf')
    for x in range(n + 1):
        sum_abs = 0
        for i in range(n):
            sum_abs += a[i] * abs(x - (i + 1))
        U = sum(a[i] * abs(x - 1) for i in range(n))
        total = 2 * (sum_abs + T + U)
        if total < min_total:
            min_total = total
    print(min_total)

if __name__ == "__main__":
    solve()
"}

