import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])
    l = list(map(int, data[2:2+m]))

    # Build constraints
    a = {}
    conflict = False
    for k in range(m - 1):
        i = l[k]
        target = l[k + 1]
        # Compute a_i
        diff = target - i
        if diff % n == 0:
            a_i = n
        else:
            a_i = diff % n
        # Check if already set
        if i in a:
            if a[i] != a_i:
                print(-1)
                return
        else:
            a[i] = a_i

    # Check if all a_i are unique
    used = set()
    for i in a.values():
        if i in used:
            print(-1)
            return
        used.add(i)

    # Fill remaining
    remaining = [x for x in range(1, n + 1) if x not in used]
    # Assign to unused positions
    unused = [i for i in range(1, n + 1) if i not in a]
    for i, v in zip(unused, remaining):
        a[i] = v

    # Output permutation
    result = [0] * n
    for idx in range(1, n + 1):
        result[idx - 1] = a.get(idx, 0)
    print(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()
"}

