def find_min_packages(n, k):
    if k >= n:
        return 1
    if n % k == 0:
        return n // k
    # Find the largest divisor of n that is <= k
    # Case 1: divisors <= sqrt(n)
    max_div = 1
    max_div_pair = 1
    # Iterate from 1 to sqrt(n)
    for i in range(1, int(n ** 0.5) + 1):
        if n % i == 0:
            if i <= k:
                max_div = max(max_div, i)
            if n // i <= k:
                max_div_pair = max(max_div_pair, n // i)
    # Case 2: divisors > sqrt(n) but <= k
    # If there exists a divisor d in (n/k, n], then n/d is <= k
    # We need to check if there's a divisor in this range
    # Let's find the smallest divisor of n that is > n/k
    found = False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            if i > n / k:
                # i is a divisor > n/k
                found = True
                break
    if found:
        # Then n/i is a divisor of n that is <= k
        # And i > n/k => n/i < k
        max_div = max(max_div, n // i)
