        # No divisor in (n/k, n] means all divisors are <= n/k
        # So the largest divisor <= k is either max_div or n/max_div_pair (if n/max_div_pair <= k)
        if n // max_div_pair <= k:
            max_div = max(max_div, n // max_div_pair)
    return max_div

