cells = []
for col_idx, height in enumerate(heights):
    for row_idx in range(height):
        cells.append((col_idx, row_idx))

# Create a bipartite graph: black cells -> white cells (right and below)
graph = [[] for _ in range(len(cells))]

# Map each cell to its index in cells list
index = {}
for i, (col, row) in enumerate(cells):
    index[(col, row)] = i

for cell_idx, (col, row) in enumerate(cells):
    # Right neighbor (same row, next column) if within bounds and current row is not empty in next column
    if col + 1 < n and row < heights[col + 1]:
        right_cell = (col + 1, row)
        if right_cell in index:
            graph[cell_idx].append(index[right_cell])

    # Below neighbor (next row, same column) if within bounds
    if row + 1 < heights[col]:
        below_cell = (col, row + 1)
        if below_cell in index:
            graph[cell_idx].append(index[below_cell])

