def solve():
    p, y = map(int, input().split())

    if p % 2 == 0:
        # All grasshoppers are even (at 2, 4, 6, ... p)
        # Reachable: all even branches >= 2
        # Answer: largest odd branch <= y
        if y % 2 == 1:
            answer = y
        else:
            answer = y - 1
    else:
        # At least one odd grasshopper (at 3, 5, ... p)
        # Reachable: all odd branches >= 3 and all even branches >= 2
        # Answer: -1
        answer = -1

    print(answer)

solve()
