def solve():
    n, k = map(int, input().split())

    # If n is odd, the last number doesn't contribute
    if n == 1:
        # Only one number, no pairs to take gcd of, total is 0
        if k == 0:
            print(1)
        else:
            print(-1)
        return

    pairs = n // 2

    # If n is odd, we have floor(n/2) pairs
    # If n is even, we have n/2 pairs

    # Let's try a better construction: use pairs like (1, 2), (3, 4), (5, 6), ...
    # Each consecutive pair gives gcd 1
    ans = []
    for i in range(1, n + 1, 2):
        ans.append(i)
        ans.append(i + 1)

    # Now verify if this gives exactly k
    score = 0
    for i in range(len(ans) - 1):
        score += gcd(ans[i], ans[i + 1])

    if score == k:
        print(' '.join(map(str, ans)))
    else:
        print(-1)

solve()
"}

