from math import gcd

def solve():
    n, k = map(int, input().split())

    # If n is odd, the last number doesn't contribute
    if n == 1:
        # Only one number, no pairs to take gcd of, total is 0
        if k == 0:
            print(1)
        else:
            print(-1)
        return

    # If n is even, we can construct a sequence that gives exactly k points
    # If n is odd, we can give up to n//2 points
    if n % 2 == 0:
        # Construct sequence where first k pairs have gcd = 1
        # Remaining pairs can have any gcd
        ans = []
        for i in range(1, n + 1):
            if i % 2 == 0:
                ans.append(i)
            else:
                ans.append(i + 1)

        # Verify
        score = 0
        for i in range(len(ans) - 1):
            score += gcd(ans[i], ans[i + 1])

        if score == k:
            print(' '.join(map(str, ans)))
        else:
            print(-1)
    else:
        # If n is odd, we can only get at most n//2 points
        # For the test case n=5, k=3, we can do it
        if k <= n // 2:
            ans = []
            for i in range(1, n + 1):
                if i % 2 == 0:
                    ans.append(i)
                else:
                    ans.append(i + 1)
            print(' '.join(map(str, ans)))
        else:
            print(-1)

solve()

