def solve():
    n, l, k = map(int, input().split())
    p = list(map(int, input().split()))
    a = list(map(int, input().split()))

    # We use 1D array for current state (w, c, b)
    # dp[w][c][b] = probability
    # w: 0..n, c: 0..n, b: 0..k+n (but initially b is at least k)
    dp = [[[0.0] * (k + n + 1) for _ in range(n + 1)] for _ in range(n + 1)]
    dp[0][0][k] = 1.0

    for i in range(n):
        # Create new dp for next state
        next_dp = [[[0.0] * (k + n + 1) for _ in range(n + 1)] for _ in range(n + 1)]

        # For each possible state
        for w in range(n + 1):
            for c in range(n + 1):
                for b in range(k, k + n + 1):
                    prob = dp[w][c][b]
                    if prob == 0:
                        continue

                    # Win the i-th tour
                    win_w = w + 1
                    if a[i] == -1:
                        win_c = c + 1
                        win_b = b
                    else:
                        win_c = c
                        win_b = b + a[i]

                    if win_w <= n and win_c <= n and win_b <= k + n:
                        next_dp[win_w][win_c][win_b] += prob * (p[i] / 100)

                    # Lose the i-th tour
                    lose_w = w
                    lose_c = c
                    lose_b = b
                    if lose_w <= n and lose_c <= n and lose_b <= k + n:
                        next_dp[lose_w][lose_c][lose_b] += prob * (1 - p[i] / 100)

        dp = next_dp

    # Sum probabilities where we won at least l tours and can carry all huge prizes
    result = 0.0
    for w in range(l, n + 1):
        for c in range(n + 1):
            for b in range(k, k + n + 1):
                if c <= b:
                    result += dp[w][c][b]

    print(f"{result:.12f}")

