def solve():
    n, l, k = map(int, input().split())
    p = list(map(int, input().split()))
    a = list(map(int, input().split()))

    # dp[w][c][b] = probability
    # w: 0..n, c: 0..n, b: k..k+n
    dp = [[[0.0] * (n + 1) for _ in range(n + 1)] for _ in range(n + 1)]
    dp[0][0][k] = 1.0

    for tour_index in range(n):
        next_dp = [[[0.0] * (n + 1) for _ in range(n + 1)] for _ in range(n + 1)]

        for wins in range(n + 1):
            for carry_needs in range(n + 1):
                for current_capacity in range(k, k + n + 1):
                    prob = dp[wins][carry_needs][current_capacity]
                    if prob == 0:
                        continue

                    # Win the tour
                    new_wins = wins + 1
                    new_carry_needs = carry_needs + 1 if a[tour_index] == -1 else carry_needs
                    new_capacity = current_capacity if a[tour_index] == -1 else current_capacity + a[tour_index]

                    if new_wins <= n and new_carry_needs <= n and new_capacity <= k + n:
                        next_dp[new_wins][new_carry_needs][new_capacity] += prob * (p[tour_index] / 100)

                    # Lose the tour
                    new_wins = wins
                    new_carry_needs = carry_needs
                    new_capacity = current_capacity
                    if new_wins <= n and new_carry_needs <= n and new_capacity <= k + n:
