from collections import defaultdict

n = int(input())
edges = defaultdict(set)

for _ in range(2 * n):
    a, b = map(int, input().split())
    edges[a].add(b)
    edges[b].add(a)

# Build adjacency list (both adjacent and distance-2)
adj = defaultdict(set)
for a, b in edges.items():
    for neighbor in b:
        adj[a].add(neighbor)

visited = set()
order = []

def dfs(current, prev):
    if current in visited:
        return False

    visited.add(current)
    order.append(current)

    if len(order) == n:
        return True

    # Try distance-2 neighbors first (excluding the previous)
    for neighbor in adj[current]:
        if neighbor != prev:
            if dfs(neighbor, current):
                return True

    order.pop()
    return False

if dfs(1, -1):
    print(' '.join(map(str, order)))
else:
    print(-1)
"}

