import heapq

def solve():
    n, m, k = map(int, input().split())

    # Organize flights by city
    graph_from = {}  # flights from city i to Metropolis (city 0)
    graph_to = {}    # flights to city i from Metropolis (city 0)

    for _ in range(m):
        di, fi, ti, ci = map(int, input().split())
        if fi == 0:  # Flight from Metropolis to city ti
            if ti not in graph_to:
                graph_to[ti] = []
            graph_to[ti].append((di, ci))
        else:  # Flight from city fi to Metropolis
            if fi not in graph_from:
                graph_from[fi] = []
            graph_from[fi].append((di, ci))

    # Dijkstra from Metropolis (city 0) to all cities
    def dijkstra(start, graph):
        dist = {i: float('inf') for i in range(n + 1)}
        dist[start] = 0
        pq = [(0, start)]

        while pq:
            d, city = heapq.heappop(pq)
            if d > dist[city]:
                continue

            if city in graph:
                for day, cost in graph[city]:
                    if d + cost < dist[day]:
                        dist[day] = d + cost
                        heapq.heappush(pq, (dist[day], day))

        return dist

    # Minimum cost to get to each city from Metropolis (shortest path)
    dist_to = dijkstra(0, graph_to)

    # Minimum cost to get from Metropolis to each city (shortest path)
    dist_from = dijkstra(0, graph_from)

    total_cost = 0
    for i in range(1, n + 1):
        if dist_from[i] <= float('inf') and dist_to[i] <= float('inf'):
            total_cost += dist_from[i] + dist_to[i]
        else:
            print(-1)
            return

    print(total_cost)

