        for r in range(n):
            for c in range(m):
                dir = grid[r][c]

                if dir == '.':
                    continue

                # Check if spider at (r, c) moving dir can be seen by Om Nom
                # starting at column j
                seen = False

                if dir == 'U':
                    # Row at time t: r - t
                    # Column at time t: c
                    # Want: r - t = t (so r = 2t) AND c = j
                    if c == j and r % 2 == 0:
                        t = r // 2
                        if t >= 0 and r - t >= 0:
                            seen = True
                elif dir == 'D':
                    # Row at time t: r + t
                    # Column at time t: c
                    # Want: r + t = t (so r = 0) AND c = j
                    if c == j and r == 0:
                        seen = True
                elif dir == 'L':
                    # Row at time t: r
                    # Column at time t: c - t
                    # Want: r = t AND c - t = j => r = t AND c = r + j
                    if r == j:
                        pass
                elif dir == 'R':
                    # Row at time t: r
                    # Column at time t: c + t
                    # Want: r = t AND c + t = j => r = t AND c = j - r
                    if r == j:
                        pass

                if seen:
                    result[j] += 1

    print(' '.join(map(str, result)))

