def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    results = []

    for _ in range(t):
        n = int(next(it))
        m = int(next(it))
        a = [int(next(it)) for _ in range(n)]
        b = [int(next(it)) for _ in range(n)]

        # Sort all applications by descending memory per convenience point
        # This is simply a_i for b=1, and a_i/2 for b=2
        apps = []
        for i in range(n):
            if b[i] == 1:
                apps.append((a[i], b[i]))  # memory, convenience
            else:
                apps.append((a[i]/2, b[i]))  # memory per convenience point, convenience

