import sys

def solve():
    n = int(sys.stdin.readline())
    actions = []
    for _ in range(n):
        actions.append(sys.stdin.readline().strip())

    # Initialize possible letters
    possible = set('abcdefghijklmnopqrstuvwxyz')

    # Track when the letter becomes uniquely determined
    uniquely_determined = False

    # Count excessive shocks
    shock_count = 0

    for action in actions:
        # Parse the action
        if action[0] == '!':  # Shock action
            _, word = action.split()
            if not uniquely_determined and len(possible) > 1:
                # Update possible letters
                possible &= set(word)
                if len(possible) == 1:
                    uniquely_determined = True
            # Count shock if uniquely determined
            if uniquely_determined:
                shock_count += 1
        elif action[0] == '.':  # Non-shock action
            _, word = action.split()
            if not uniquely_determined and len(possible) > 1:
                # Update possible letters
                possible -= set(word)
                if len(possible) == 1:
                    uniquely_determined = True
            # No shock, so no increment
        elif action[0] == '?':  # Guess
            _, guess = action.split()
            if not uniquely_determined and len(possible) > 1:
                # Update possible letters
                if guess in possible:
                    possible -= {guess}
                else:
                    possible &= {guess}
                if len(possible) == 1:
                    uniquely_determined = True
            # If uniquely determined and guess is wrong
            if uniquely_determined and guess not in possible:
                shock_count += 1
            # If uniquely determined and guess is correct, break
            if uniquely_determined and guess in possible:
                break

