def place_knights(n):
    # Pattern for n=7: (0,0), (1,0), (1,3), (2,0), (3,0), (3,3), (4,0)
    # For larger n, we need to extend this pattern

    knights = []
    for i in range(n):
        if i % 3 == 0:
            knights.append((i // 3, 0))
        elif i % 3 == 1:
            knights.append((i // 3, 3))
        else:
            knights.append((i // 3, 0))

