n, m = map(int, input().split())
i, j = map(int, input().split())

# Convert to 0-indexed
col = j - 1
row = i - 1

# If already at bottom row
if row == n - 1:
    print("0.0000000000")
    exit()

# Expected steps from each position
e = [[0.0 for _ in range(m)] for _ in range(n)]

# Last row (bottom row)
for c in range(m):
    e[n-1][c] = 0.0

# Process rows from bottom to top (excluding last row)
for r in range(n-2, -1, -1):
    # Set up linear system for this row
    # For each column c:
    # k = 1 (stay) + (c > 0) + (c < m-1) + (r < n-1)

    # We need to solve a system of equations
    # Let's solve column by column, but need to handle dependencies properly

    for c in range(m):
        k = 1
        if c > 0:
            k += 1
        if c < m - 1:
            k += 1
        if r < n - 1:
            k += 1

        # Set up equation
        if k == 1:
            pass  # Already at bottom row, shouldn't happen
        elif k == 2:
            if c == 0:
                # Can stay and down
                e[r][c] = 2 + e[r+1][c]
            elif c == m - 1:
                # Can stay and down
                e[r][c] = 2 + e[r+1][c]
            else:
                # Can stay and (left or right)
                # Actually, with k=2, we can only move 1 other direction besides stay
                # If we can move left, then: E = 1 + (E + E[r][c-1]) / 2
                # E = 2 + E[r][c-1]
                if c > 0:
                    e[r][c] = 2 + e[r][c-1]
                else:
                    e[r][c] = 2 + e[r][c+1]
        elif k == 3:
            if c == 0:
                # Can stay, down, right
                e[r][c] = (3.0 + e[r][c+1] + e[r+1][c]) / 2.0
            elif c == m - 1:
                # Can stay, down, left
                e[r][c] = (3.0 + e[r][c-1] + e[r+1][c]) / 2.0
            else:
                # Can stay, down, left, and right? Actually, with k=3, we can only move 2 other directions besides stay
                # If we can move left, right, and down, then we have 4 moves, so k=4
                pass
        elif k == 4:
            e[r][c] = (4.0 + e[r][c-1] + e[r][c+1] + e[r+1][c]) / 3.0

print(f"{e[row][col]:.10f}")
"}

