    first_line = sys.stdin.readline().split()
    N, M = int(first_line[0]), int(first_line[1])
    second_line = sys.stdin.readline().split()
    i, j = int(second_line[0]), int(second_line[1])

    # If already at bottom row
    if i == N:
        print("0.0000000000")
        return

    # Initialize expected steps matrix
    dp = [[0.0 for _ in range(M + 1)] for _ in range(N + 1)]

    # Fill from bottom up
    for row in range(N - 1, 0, -1):
        if j == 1:
            # Special case: initial column is 1, compute from left to right
            for col in range(1, M + 1):
                if col == 1:
                    dp[row][col] = 1.5 + dp[row][col + 1] / 2 + dp[row + 1][col] / 2
                elif col == M:
                    dp[row][col] = 1.5 + dp[row][col - 1] / 2 + dp[row + 1][col] / 2
                else:
                    dp[row][col] = 1.3333333333 + dp[row][col - 1] / 3 + dp[row][col + 1] / 3 + dp[row + 1][col] / 3
        elif j == M:
            # Special case: initial column is M, compute from right to left
            for col in range(M, 0, -1):
                if col == 1:
                    dp[row][col] = 1.5 + dp[row][col + 1] / 2 + dp[row + 1][col] / 2
