    while i < n:
        if target_sum == 0:
            # We've found all segments
            segments.append((i, n-1))
            break

        current_sum = int(ticket[i])
        if current_sum > target_sum:
            break

        for j in range(i + 1, n):
            current_sum += int(ticket[j])
            if current_sum > target_sum:
                break

        if current_sum == target_sum:
            segments.append((i, j))
            i = j + 1
            target_sum = total_sum - target_sum
        else:
            break

    # Check if we found enough segments
    if len(segments) >= 2:
        print("YES")
    else:
        print("NO")
