# Read input
text = input().strip()
p, y = map(int, text.split())

# Find the highest suitable branch from y down to 2
# A branch is suitable if it is not divisible by any number from 2 to p
# and it is not occupied by a grasshopper (i.e., not in [2, p])

# Try from y down to 2
for k in range(y, 1, -1):
    if k <= p:
        continue  # Grasshoppers are at branches 2 to p, these are occupied
    # Check if k is not divisible by any number from 2 to p
    is_suitable = True
    for x in range(2, p + 1):
        if k % x == 0:
            is_suitable = False
            break
    if is_suitable:
        print(k)
        break
else:
    print(-1)
"}

