for i in range(7):
    result += sequence[i]

# Remaining eggs
# After the first 7, we cycle through GBIV (indices 3, 4, 5, 6)
for i in range(7, n):
    # Calculate which character to add from GBIV
    # Cycle through 0->3, 1->4, 2->5, 3->6
    pos_in_gbiv = (i - 7) % 4
    if pos_in_gbiv == 0:
        result += sequence[3]
    elif pos_in_gbiv == 1:
