import math

def solve() -> None:
    n, m, x = map(int, input().split())
    keyboard = [input().strip() for _ in range(n)]

    # Precompute positions
    letter_pos = [[] for _ in range(26)]  # 0:a ... 25:z
    s_pos = []

    for i in range(n):
        for j in range(m):
            c = keyboard[i][j]
            if c == 'S':
                s_pos.append((i, j))
            else:
                idx = ord(c) - ord('a')
                letter_pos[idx].append((i, j))

    has_shift = len(s_pos) > 0

    # Precompute for each letter the min distance to any 'S'
    # If no 'S', dist is infinity
    dist_to_s = [float('inf')] * 26

    if has_shift:
        for letter_idx in range(26):
            if letter_pos[letter_idx]:
                min_d = float('inf')
                for s in s_pos:
                    s_i, s_j = s
                    for l_pos in letter_pos[letter_idx]:
                        l_i, l_j = l_pos
                        d = math.hypot(s_i - l_i, s_j - l_j)
                        if d < min_d:
                            min_d = d
                dist_to_s[letter_idx] = min_d

    q = int(input())
    text = input().strip()

    ans = 0

    for c in text:
        if 'a' <= c <= 'z':
            l = ord(c) - ord('a')
            if not letter_pos[l]:
                print(-1)
                return
        else:  # uppercase
            l = ord(c.lower()) - ord('a')
            if not has_shift or not letter_pos[l]:
                print(-1)
                return
            if dist_to_s[l] > x:
                ans += 1

    print(ans)

if __name__ == "__main__":
    solve()
"}

