def solve():
    data = sys.stdin.read().strip().split()
    t = int(data[0])
    idx = 1
    out = []

    for _ in range(t):
        n = int(data[idx])
        k = int(data[idx + 1])
        idx += 2

        if k >= n:
            out.append(1)
            continue

        max_div = 1
        limit = int(math.isqrt(n)) + 1

        for i in range(1, limit):
            if n % i == 0:
                divisor1 = i
                divisor2 = n // i

                if divisor1 <= k:
                    max_div = max(max_div, divisor1)

                if divisor2 <= k:
                    max_div = max(max_div, divisor2)

        out.append(n // max_div)

    sys.stdout.write("\n".join(map(str, out)))

if __name__ == "__main__":
    solve()
